//! # Responsibility
//!
//! This module is responsible for writing the Markdown help manual to disk:
//! the per-leaf pages and the index page, validated and written so a failure
//! never mixes Clio's generated files with a directory's other content.
//!
//! ## Owns
//! - `write_manual`, the validate-all-then-write entry point the help dispatch
//!   calls
//! - The manual's render: one page per registered leaf command, sorted, plus
//!   the index page
//! - The generated-by marker that decides which files this command may replace
//! - The pre-write boundary checks over `--out`: symlink components, symlink
//!   targets, traversal, and target collisions (directories, non-regular
//!   files, and files this command did not generate)
//! - The same-directory temp-sibling write: create-new, write, sync, rename
//! - The test-only promote-failure seam (absent from production builds)
//!
//! ## Does not own
//! - A single page's Markdown (see `cli_help_markdown`)
//! - The registry records rendered (see `cli_command_registry`)
//! - The `--markdown`/`--out` argument validation (see `cli_top_level`)
//! - The CLI error shape and exit codes (see `cli_error`)
//!
//! ## Boundary
//!
//! Changes to which files the manual writes and how a write happens should
//! normally require changes here. Changes to a page's Markdown should not.
//!
//! Keep this module focused on the bounded manual write.

use crate::cli_command_registry;
use crate::cli_command_spec::CommandSpec;
use crate::cli_error::CliError;
use crate::cli_help_markdown::{PageMap, render_command_page};
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

/// The first line of every file this command generates.
///
/// A target file is replaced only when its first line is this marker, so an
/// unrelated file whose name collides with a page is a refusal, never a
/// replacement. The marker is static text: no build date, no host path.
const GENERATED_MARKER: &str =
    "<!-- generated by `clio help --markdown`; edits to this file are replaced -->";

/// One manual file: its page name inside `--out` and its bytes.
struct Page {
    file: String,
    bytes: String,
}

/// The whole manual: the per-leaf pages in write order, then the index.
struct Manual {
    pages: Vec<Page>,
    index: Page,
}

impl Manual {
    /// Every file in write order: the pages sorted by page name, then the
    /// index, so a run that stops early leaves no index promising pages it
    /// never wrote.
    fn write_order(&self) -> impl Iterator<Item = &Page> {
        self.pages.iter().chain(std::iter::once(&self.index))
    }
}

/// Render the whole manual without touching the disk: one page per registered
/// leaf command, plus the index.
fn render_manual() -> Manual {
    let specs: Vec<&CommandSpec> = cli_command_registry::all().collect();
    let page_map = PageMap::new(specs.iter().map(|spec| spec.name));
    let mut entries: Vec<(&CommandSpec, String)> = specs
        .iter()
        .map(|spec| {
            let file = page_map
                .page(spec.name)
                .expect("every registered name has a page")
                .to_owned();
            (*spec, file)
        })
        .collect();
    entries.sort_unstable_by(|a, b| a.0.name.cmp(b.0.name));
    let index_entries: Vec<(&str, String)> = entries
        .iter()
        .map(|(spec, file)| (spec.name, file.clone()))
        .collect();
    let mut pages: Vec<Page> = entries
        .iter()
        .map(|(spec, file)| Page {
            file: file.clone(),
            bytes: marked(&render_command_page(spec, &page_map)),
        })
        .collect();
    pages.sort_unstable_by(|a, b| a.file.cmp(&b.file));
    Manual {
        pages,
        index: Page {
            file: PageMap::index_page().to_owned(),
            bytes: marked(&index_text(&index_entries)),
        },
    }
}

/// The index page: its title, then one sorted link per leaf page.
fn index_text(entries: &[(&str, String)]) -> String {
    let mut text = String::from("# clio help index\n\n");
    for (name, file) in entries {
        text.push_str("- [");
        text.push_str(name);
        text.push_str("](");
        text.push_str(file);
        text.push_str(")\n");
    }
    text
}

/// `page` with the generated-by marker as its first line.
fn marked(page: &str) -> String {
    format!("{GENERATED_MARKER}\n{page}")
}

/// Write the manual into `out_dir`, replacing only files this command
/// generated.
///
/// Everything is validated before the first byte is written: every `--out`
/// component is a real directory, no component is a symlink (see
/// `check_directory` for the accepted limitation), and every target is absent
/// or a file this command generated. `out_dir` is created only after those
/// checks pass; the targets are then checked once more, because a component
/// created in between can change how the path resolves (a missing component
/// followed by `..`). The page map has already collision-checked the page
/// names, so the index and the pages never share a name. Each file is written
/// through a same-directory temp sibling created with create-new, synced, and
/// promoted with rename. A failure after the first promotion leaves the files
/// already written in place and reports the step that failed, because std has
/// no multi-file atomic swap.
///
/// # Errors
/// A directory, target, or write failure, as a `usage` error for a refused
/// path and an operational error for a write step.
pub(crate) fn write_manual(out_dir: &Path) -> Result<(), CliError> {
    let manual = render_manual();
    check_directory(out_dir)?;
    for page in manual.write_order() {
        check_target(out_dir, &page.file)?;
    }
    fs::create_dir_all(out_dir).map_err(|err| io_error("create", out_dir, &err))?;
    // The creation can change how `out_dir` resolves, so every target is
    // checked again against the resolution the write loop below will use.
    for page in manual.write_order() {
        check_target(out_dir, &page.file)?;
    }
    for page in manual.write_order() {
        write_page(out_dir, page)?;
    }
    Ok(())
}

/// Check `out_dir` before anything is written: every existing component is a
/// real directory, and `--out` deliberately refuses every symlink component.
/// The create and the rename later resolve the path again, so a component
/// swapped concurrently to a link in between is outside the checked guarantee
/// (accepted limitation).
fn check_directory(out_dir: &Path) -> Result<(), CliError> {
    let components: Vec<_> = out_dir.components().collect();
    if components.is_empty() {
        return Err(CliError::usage("--out is empty"));
    }
    let mut walked = PathBuf::new();
    for component in components {
        walked.push(component);
        let meta = match fs::symlink_metadata(&walked) {
            Ok(meta) => meta,
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => continue,
            Err(err) => return Err(io_error("inspect", &walked, &err)),
        };
        if meta.file_type().is_symlink() {
            return Err(CliError::usage(format!(
                "--out refuses the symlink at `{}`; every path component must be a real directory",
                walked.display()
            )));
        }
        if !meta.is_dir() {
            return Err(CliError::usage(format!(
                "--out `{}` is not a directory",
                walked.display()
            )));
        }
    }
    Ok(())
}

/// Check one page target: absent, generated by this command, or refused. A
/// symlink, a directory, any other non-regular file (a FIFO or a device node),
/// or a file this command did not generate is refused rather than replaced, so
/// unrelated content never disappears and a special file is never opened.
fn check_target(out_dir: &Path, file: &str) -> Result<(), CliError> {
    if file.is_empty() || file == "." || file == ".." || file.contains('/') || file.contains('\\') {
        return Err(CliError::usage(format!(
            "page name `{file}` is not a plain file name"
        )));
    }
    let target = out_dir.join(file);
    let meta = match fs::symlink_metadata(&target) {
        Ok(meta) => meta,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(err) => return Err(io_error("inspect", &target, &err)),
    };
    if meta.file_type().is_symlink() {
        return Err(CliError::usage(format!(
            "refuses to replace the symlink at `{}`",
            target.display()
        )));
    }
    if meta.is_dir() {
        return Err(CliError::usage(format!(
            "refuses `{}`: a directory sits in a page's place",
            target.display()
        )));
    }
    if !meta.file_type().is_file() {
        return Err(CliError::usage(format!(
            "refuses `{}`: it is not a regular file",
            target.display()
        )));
    }
    if !generated(&target)? {
        return Err(CliError::usage(format!(
            "refuses to replace `{}`: it was not generated by `clio help --markdown`",
            target.display()
        )));
    }
    Ok(())
}

/// Whether `path`'s first line is the generated-by marker.
fn generated(path: &Path) -> Result<bool, CliError> {
    let bytes = fs::read(path).map_err(|err| io_error("read", path, &err))?;
    let first_line = match bytes.iter().position(|byte| *byte == b'\n') {
        Some(end) => &bytes[..end],
        None => bytes.as_slice(),
    };
    Ok(first_line == GENERATED_MARKER.as_bytes())
}

/// Write one page through a same-directory temp sibling, the pattern
/// `agent_harness_write::write_json_atomic` uses without its symlink-following
/// policy: the temp file is created with create-new and the mode applied,
/// written, synced, and promoted with rename. On any failure the temp file is
/// removed and the error names the step.
fn write_page(out_dir: &Path, page: &Page) -> Result<(), CliError> {
    let target = out_dir.join(&page.file);
    let mode = existing_mode(&target).unwrap_or(0o644);
    let (tmp, file) = create_temp(&target, mode)?;
    if let Err(err) = write_and_sync(file, page.bytes.as_bytes(), mode, &tmp) {
        let _ = fs::remove_file(&tmp);
        return Err(incomplete(out_dir, &err));
    }
    if let Err(err) = promote(&tmp, &target) {
        let _ = fs::remove_file(&tmp);
        return Err(incomplete(out_dir, &io_error("promote", &target, &err)));
    }
    Ok(())
}

/// Rename the temp sibling over its target: the promote step.
///
/// Production builds are the plain rename. A test-only seam can make this one
/// step fail for one exact target so the real failure path runs in a test; the
/// seam and its branch are both absent from production builds.
fn promote(tmp: &Path, target: &Path) -> std::io::Result<()> {
    #[cfg(test)]
    {
        let armed = FAILED_PROMOTE_TARGET
            .lock()
            .expect("the promote seam lock is not poisoned");
        if armed.as_deref() == Some(target) {
            return Err(std::io::Error::other(format!(
                "the promote step was made to fail for {}",
                target.display()
            )));
        }
    }
    fs::rename(tmp, target)
}

/// The target whose promote step fails while the test seam is armed. Test-only:
/// absent from production builds, so nothing can consult it there.
#[cfg(test)]
static FAILED_PROMOTE_TARGET: std::sync::Mutex<Option<PathBuf>> = std::sync::Mutex::new(None);

/// The failure a write step reports: which step failed, and that the manual in
/// the directory is now incomplete.
fn incomplete(out_dir: &Path, error: &CliError) -> CliError {
    CliError::operational(
        "manual_incomplete",
        format!(
            "{} The manual in `{}` is incomplete.",
            error.message(),
            out_dir.display()
        ),
    )
}

/// A hidden temp sibling beside `target`, unique across threads and processes.
fn temp_sibling(target: &Path) -> PathBuf {
    static TEMP_SEQ: AtomicU64 = AtomicU64::new(0);
    let name = target
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("page.md");
    let pid = std::process::id();
    let nanos = unix_nanos();
    let seq = TEMP_SEQ.fetch_add(1, Ordering::Relaxed);
    target.with_file_name(format!(".{name}.{pid}.{nanos}.{seq}.tmp"))
}

/// Create a new temp sibling of `target` with `mode` already applied, so the
/// file never exists with wider permissions. A leftover name from a crashed
/// run is skipped.
fn create_temp(target: &Path, mode: u32) -> Result<(PathBuf, fs::File), CliError> {
    for _ in 0..10 {
        let tmp = temp_sibling(target);
        match open_new(&tmp, mode) {
            Ok(file) => return Ok((tmp, file)),
            Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => {}
            Err(err) => return Err(io_error("create", &tmp, &err)),
        }
    }
    Err(CliError::operational(
        "manual_write",
        format!("failed to create a temp file beside {}", target.display()),
    ))
}

#[cfg(unix)]
fn open_new(tmp: &Path, mode: u32) -> std::io::Result<fs::File> {
    use std::os::unix::fs::OpenOptionsExt;
    fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(mode)
        .open(tmp)
}

#[cfg(not(unix))]
fn open_new(tmp: &Path, _mode: u32) -> std::io::Result<fs::File> {
    fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(tmp)
}

/// Write `bytes` to the temp `file`, restore the exact mode in case the
/// process mask narrowed it at creation, and sync to disk before the caller
/// renames the temp file over its target.
fn write_and_sync(file: fs::File, bytes: &[u8], mode: u32, tmp: &Path) -> Result<(), CliError> {
    use std::io::Write;
    let mut file = file;
    file.write_all(bytes)
        .map_err(|err| io_error("write", tmp, &err))?;
    set_mode(tmp, mode).map_err(|err| io_error("set permissions on", tmp, &err))?;
    file.sync_all().map_err(|err| io_error("sync", tmp, &err))
}

/// The `target`'s existing mode, read without following a link: the pre-write
/// checks have already refused symlinks, so a link here is refused too.
#[cfg(unix)]
fn existing_mode(target: &Path) -> Option<u32> {
    use std::os::unix::fs::PermissionsExt;
    fs::symlink_metadata(target)
        .ok()
        .map(|meta| meta.permissions().mode() & 0o7777)
}

#[cfg(not(unix))]
fn existing_mode(_target: &Path) -> Option<u32> {
    None
}

#[cfg(unix)]
fn set_mode(path: &Path, mode: u32) -> std::io::Result<()> {
    use std::os::unix::fs::PermissionsExt;
    fs::set_permissions(path, fs::Permissions::from_mode(mode))
}

#[cfg(not(unix))]
fn set_mode(_path: &Path, _mode: u32) -> std::io::Result<()> {
    Ok(())
}

fn unix_nanos() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |since| since.as_nanos())
}

fn io_error(action: &str, path: &Path, err: &std::io::Error) -> CliError {
    CliError::operational(
        "manual_write",
        format!("failed to {action} {}: {err}", path.display()),
    )
}

